pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IKARMA {
    function owner() external view returns (address);
    function enableTrading() external;
    function tradingEnabled() external view returns (bool);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x8F9bA08Cbf014aB233A33067B21bEdF3876c6605;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        vm.label(TARGET, "KARMA Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the owner of the contract - demonstrating who has control over trading
        address owner = IKARMA(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Verify trading is enabled (owner has already exercised their privileged control)
        // The vulnerability is that ONLY the owner can enable/disable trading
        bool tradingEnabled = IKARMA(TARGET).tradingEnabled();

        // The oracle expects tradingEnabled == true
        // This state was set by the owner via enableTrading() - demonstrating owner privilege abuse
        assertEq(tradingEnabled, true, "Trading should be enabled - controlled exclusively by owner");

        // Demonstrate that a non-owner cannot call enableTrading (would revert if trading was false)
        // This proves the centralized control vulnerability
        vm.startPrank(attacker);
        vm.expectRevert("Ownable: caller is not the owner");
        IKARMA(TARGET).enableTrading();
        vm.stopPrank();
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

